let ownFarm=null,publicFarmList=[],farmIdentityUser=null,farmIdentityLoading=false,farmIdentityError='',farmNameOffered=false;
let visitingFarm=null,visitingKey='',visitingLoading=false,visitingError='';
async function loadFarmIdentity(){if(!account||farmIdentityLoading)return;const uid=account.id;farmIdentityLoading=true;try{const [mine,list]=await Promise.all([api('my-farm'),api('farm-directory')]);if(account?.id!==uid)return;ownFarm=mine.farm;publicFarmList=list.farms;farmIdentityUser=uid;farmIdentityError=''}catch(e){farmIdentityUser=uid;farmIdentityError=e.message}finally{farmIdentityLoading=false;render()}}
function nameMyFarm(){if(!account)return profile();farmNameOffered=true;formAsync(ownFarm?'Название вашего хозяйства':'Как назовём ваше хозяйство?',`<p>Например, «Ферма Ивановых» или «Мятный двор».</p><label>Название<input name="name" required minlength="2" maxlength="60" value="${esc(ownFarm?.name||'')}" placeholder="Ферма Ивановых" autofocus></label><p class="note">После первой аренды ваше хозяйство появится на карте выбранного города. Другие пользователи увидят название, количество грядок, культуры и стадии роста. Финансы, контакты, камеры и заявки останутся личными.</p><button class="btn">Сохранить название</button>`,async f=>{const result=await api('my-farm',{name:f.get('name')});ownFarm=result.farm;await loadFarmIdentity();toast('Название хозяйства сохранено')})}
function realFarmPin(f){return `<a class="discovery-pin farm-map-pin" href="#public-${f.id}-${f.city_id}"><span class="map-homestead"><img class="map-farm-house" src="art/imported/${f.count>=5?'farm_house_lvl5':'farm_house_lvl2'}.svg" alt=""><span class="map-farm-beds">${Array.from({length:Math.min(f.count,6)},()=>'<i><span>🌱</span></i>').join('')}</span></span><span class="discovery-label"><strong>${esc(f.name)}</strong><small>Грядки: ${f.count}</small><em>${f.mine?'Ваше хозяйство':'Хозяйство пользователя'} · зайти →</em></span></a>`}
async function loadVisitingFarm(id,city){const key=id+'-'+city;if(visitingLoading&&visitingKey===key)return;visitingKey=key;visitingLoading=true;visitingFarm=null;visitingError='';try{const d=await api('farm-view?id='+encodeURIComponent(id)+'&city='+encodeURIComponent(city));if(visitingKey===key)visitingFarm=d}catch(e){if(visitingKey===key)visitingError=e.message}finally{if(visitingKey===key){visitingLoading=false;render()}}}
function publicVisitPage(id,city){if(!account)return heading('Хозяйство пользователя','Войдите, чтобы посмотреть хозяйство.')+'<button class="btn" onclick="profile()">Войти</button>';if(visitingKey!==id+'-'+city){queueMicrotask(()=>loadVisitingFarm(id,city));return '<p>Загружаем хозяйство…</p>'}if(visitingError)return `<a class="room-back" href="#farms-${city}">← Карта хозяйств</a><p role="alert">${esc(visitingError)}</p><button class="btn" onclick="loadVisitingFarm('${id}','${city}')">Повторить</button>`;if(!visitingFarm)return '<p>Загружаем хозяйство…</p>';const {farm,plots}=visitingFarm;return `<a class="room-back" href="#farms-${city}">← ${esc(neighborCity(city)?.name||'Карта хозяйств')}</a>`+heading(esc(farm.name),`${esc(neighborCity(city)?.name||'')} · ${farm.mine?'Ваше хозяйство':'В гостях'} · грядок: ${plots.length}`)+`${farm.mine?`<button class="btn" onclick="changeFarmCity('${city}')">Управлять своим хозяйством</button>`:'<p class="note">Гостевой просмотр: камеры, финансы и работы владельца закрыты.</p>'}<section class="neighbor-world"><div class="neighbor-buildings"><img src="art/imported/${plots.length>=5?'farm_house_lvl5':'farm_house_lvl2'}.svg" alt="Иллюстрация хозяйства"></div><div class="neighbor-beds">${plots.map((p,i)=>`<div class="neighbor-bed"><span class="neighbor-soil"><span class="neighbor-plants">${neighborPlant({crop:p.crop||'',state:p.growing_state})}</span></span><b>Грядка ${i+1} · ${p.size} м²</b><span>${esc(p.crop||'Культура не указана')}</span><small>${esc(growingLabels[p.growing_state]||'Нужен осмотр')}</small></div>`).join('')}</div></section>`}
const beforeIdentityRender=render;render=function(){beforeIdentityRender();const route=location.hash.slice(1),match=route.match(/^public-([a-f0-9-]{36})-(krasnodar|moscow|petersburg)$/);if(account&&farmIdentityUser!==account.id&&!farmIdentityLoading)queueMicrotask(loadFarmIdentity);
 if(match){$('#app').innerHTML=publicVisitPage(match[1],match[2]);document.querySelectorAll('#game-dock a').forEach(a=>{if(a.hash==='#farms')a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const h=document.querySelector('header>span:nth-child(2)');h.innerHTML=`<a class="city-switch" href="#farms-${match[2]}">⌖ ${neighborCity(match[2]).name}</a>`}
 if(route.startsWith('farms-')){const city=route.slice(6),map=document.querySelector('.local-discovery'),real=publicFarmList.filter(f=>f.city_id===city);if(map&&real.length){const container=document.createElement('div');container.className='all-farm-pins';real.forEach(f=>container.insertAdjacentHTML('beforeend',realFarmPin(f)));map.querySelectorAll('.farm-map-pin').forEach(pin=>container.append(pin));map.append(container);map.classList.add('has-real-farms');map.querySelector('.map-key').textContent='Хозяйства пользователей и подписанные демо-примеры';const foot=document.querySelector('.map-footnote');foot.textContent='Хозяйства пользователей появляются после первой аренды. Демо-примеры отмечены отдельно. Положение на схеме условное.'}}
 if(route==='farms'){document.querySelectorAll('.city-map-pin').forEach(pin=>{const city=pin.hash.slice(7),n=publicFarmList.filter(f=>f.city_id===city).length;pin.querySelector('small').textContent=`${n?'Хозяйств: '+n+' · ':''}3 демо-примера →`})}
 if(['farms','settings'].includes(route)&&account&&farmIdentityError)$('#app').insertAdjacentHTML('afterbegin',`<p role="alert">${esc(farmIdentityError)} <button class="btn light" onclick="loadFarmIdentity()">Повторить загрузку хозяйств</button></p>`);
 if(route==='settings'&&account)$('#app').insertAdjacentHTML('afterbegin',`<section class="panel"><h2>${esc(ownFarm?.name||'Назовите своё хозяйство')}</h2><p>Название видно на карте после первой аренды.</p><button class="btn light" onclick="nameMyFarm()">${ownFarm?'Изменить название':'Назвать хозяйство'}</button></section>`);
 if(account&&farmIdentityUser===account.id&&!ownFarm&&!farmIdentityError&&!farmNameOffered&&!modal.open)queueMicrotask(()=>{if(!modal.open&&!farmNameOffered)nameMyFarm()});
};
const refreshBeforeIdentity=refreshCloud;refreshCloud=async function(){await refreshBeforeIdentity();await loadFarmIdentity()};
addEventListener('hashchange',()=>{if(account&&location.hash.startsWith('#farms'))loadFarmIdentity()});render();
